-- Phase 3a: step_translations batch 1 — carrot cake (1 recipe, 5 steps) + roasted fruits (6 steps)
-- Hand-translated instructions + hints, all 4 non-EN locales.

INSERT INTO step_translations (instruction_en, instruction_fr, instruction_es, instruction_de, instruction_pt, hint_en, hint_fr, hint_es, hint_de, hint_pt) VALUES
  -- 1. Carrot cake step 1
  ('In a medium saucepan, combine milk, heavy cream, shredded carrots, white sugar, brown sugar, and cinnamon. Stir over medium heat.',
   'Dans une casserole moyenne, mélanger le lait, la crème épaisse, les carottes râpées, le sucre blanc, la cassonade et la cannelle. Remuer à feu moyen.',
   'En una cacerola mediana, combinar la leche, la crema espesa, las zanahorias ralladas, el azúcar blanco, el azúcar moreno y la canela. Remover a fuego medio.',
   'In einem mittelgroßen Topf Milch, Sahne, geriebene Karotten, weißen Zucker, braunen Zucker und Zimt verrühren. Bei mittlerer Hitze umrühren.',
   'Numa panela média, combine o leite, o creme de leite, as cenouras raladas, o açúcar branco, o açúcar mascavo e a canela. Mexa em fogo médio.',
   'Use finely shredded carrots for the smoothest texture — a microplane or fine box grater works best.',
   'Utilisez des carottes finement râpées pour une texture plus lisse — une microplane ou une râpe à trous fins fonctionne le mieux.',
   'Usa zanahorias finamente ralladas para una textura más suave — una microplane o un rallador de caja fino funciona mejor.',
   'Verwende fein geriebene Karotten für die glatteste Textur — eine Microplane oder feine Kastenreibe eignet sich am besten.',
   'Use cenouras raladas finamente para a textura mais lisa — um ralador microplane ou ralador fino funciona melhor.'),

  -- 2. Carrot cake step 2
  ('Simmer for 5 minutes until the carrots are soft.',
   'Laisser mijoter 5 minutes jusqu''à ce que les carottes soient tendres.',
   'Cocinar a fuego lento durante 5 minutos hasta que las zanahorias estén blandas.',
   'Bei geringer Hitze 5 Minuten köcheln lassen, bis die Karotten weich sind.',
   'Cozinhe em fogo baixo por 5 minutos até as cenouras ficarem macias.',
   'Keep the heat at medium-low to avoid scorching the cream. Stir occasionally.',
   'Maintenez le feu à moyen-doux pour éviter de brûler la crème. Remuez de temps en temps.',
   'Mantén el fuego a medio-bajo para evitar que la crema se queme. Remueve de vez en cuando.',
   'Halte die Hitze auf mittel-niedrig, damit die Sahne nicht anbrennt. Gelegentlich umrühren.',
   'Mantenha o fogo entre médio-baixo para evitar queimar o creme. Mexa de vez em quando.'),

  -- 3. Carrot cake step 3
  ('Remove from heat. Add cream cheese and vanilla extract, stirring until smooth and fully combined.',
   'Retirer du feu. Ajouter le fromage à la crème et l''extrait de vanille, en remuant jusqu''à ce que le mélange soit lisse et homogène.',
   'Retirar del fuego. Añadir el queso crema y el extracto de vainilla, removiendo hasta que esté suave y totalmente integrado.',
   'Vom Herd nehmen. Frischkäse und Vanilleextrakt einrühren, bis die Masse glatt und vollständig verbunden ist.',
   'Retire do fogo. Adicione o cream cheese e o extrato de baunilha, mexendo até ficar liso e totalmente combinado.',
   'Softened cream cheese blends in more easily — let it sit at room temperature for 10 minutes beforehand.',
   'Le fromage à la crème ramolli s''incorpore plus facilement — laissez-le à température ambiante pendant 10 minutes au préalable.',
   'El queso crema ablandado se integra más fácilmente — déjalo a temperatura ambiente durante 10 minutos antes.',
   'Weicher Frischkäse lässt sich leichter verrühren — 10 Minuten vorher bei Raumtemperatur stehen lassen.',
   'Cream cheese amolecido se mistura mais fácil — deixe-o em temperatura ambiente por 10 minutos antes.'),

  -- 4. Carrot cake step 4
  ('Pour the base into a Ninja Creami pint container and let it cool to room temperature. Freeze for 24 hours.',
   'Verser la base dans un pot Ninja Creami et laisser refroidir à température ambiante. Congeler pendant 24 heures.',
   'Verter la base en un recipiente Ninja Creami y dejar que se enfríe a temperatura ambiente. Congelar durante 24 horas.',
   'Die Basis in einen Ninja-Creami-Becher gießen und auf Raumtemperatur abkühlen lassen. 24 Stunden einfrieren.',
   'Despeje a base no pote Ninja Creami e deixe esfriar em temperatura ambiente. Congele por 24 horas.',
   'Place on a flat, level surface in the coldest part of your freezer. Do not add mix-ins yet.',
   'Placez sur une surface plane et horizontale dans la partie la plus froide du congélateur. N''ajoutez pas encore les mix-ins.',
   'Coloca sobre una superficie plana y nivelada en la parte más fría del congelador. No añadas mix-ins todavía.',
   'Auf eine ebene, waagerechte Fläche im kältesten Teil des Gefrierschranks stellen. Noch keine Mix-Ins hinzufügen.',
   'Coloque numa superfície plana e nivelada na parte mais fria do freezer. Não adicione mix-ins ainda.'),

  -- 5. Carrot cake step 5
  ('Make a small hole in the center. Add toasted walnuts, shredded coconut, and golden raisins. Process using the Mix-In function.',
   'Faire un petit trou au centre. Ajouter les noix grillées, la noix de coco râpée et les raisins dorés. Lancer la fonction Mix-In.',
   'Hacer un pequeño agujero en el centro. Añadir las nueces tostadas, el coco rallado y las pasas doradas. Procesar con la función Mix-In.',
   'Ein kleines Loch in die Mitte bohren. Geröstete Walnüsse, Kokosraspeln und goldene Rosinen hinzufügen. Mit der Mix-In-Funktion verarbeiten.',
   'Faça um pequeno furo no centro. Adicione as nozes torradas, o coco ralado e as passas douradas. Processe com a função Mix-In.',
   'Create a hole down to about halfway. Don''t overfill — the blade needs room to distribute the mix-ins evenly.',
   'Creusez un trou jusqu''à mi-hauteur environ. Ne pas trop remplir — la lame a besoin d''espace pour répartir uniformément les mix-ins.',
   'Haz un agujero hasta aproximadamente la mitad. No lo llenes demasiado — la cuchilla necesita espacio para distribuir los mix-ins de manera uniforme.',
   'Das Loch bis etwa zur Hälfte nach unten bohren. Nicht zu voll machen — die Klinge braucht Platz, um die Mix-Ins gleichmäßig zu verteilen.',
   'Faça o furo até cerca da metade. Não encha demais — a lâmina precisa de espaço para distribuir os mix-ins de maneira uniforme.'),

  -- 6. Roast strawberries
  ('Roast the strawberries: preheat oven to 400°F (200°C). Toss halved strawberries with 1 teaspoon of the granulated sugar on a parchment-lined tray and roast for 20 minutes until jammy and slightly caramelized. Cool completely, then blend into a smooth puree. You should have about 1/3 cup.',
   'Rôtir les fraises : préchauffer le four à 200°C. Mélanger les fraises coupées en deux avec 1 cuillère à café de sucre en poudre sur une plaque recouverte de papier sulfurisé et rôtir 20 minutes jusqu''à ce qu''elles soient confites et légèrement caramélisées. Laisser refroidir complètement, puis mixer en purée lisse. Vous devriez obtenir environ 1/3 tasse.',
   'Asar las fresas: precalentar el horno a 200°C (400°F). Mezclar las fresas partidas por la mitad con 1 cucharadita del azúcar granulado sobre una bandeja forrada con papel pergamino y asar durante 20 minutos hasta que queden mermeladas y ligeramente caramelizadas. Enfriar completamente, luego licuar hasta obtener un puré suave. Deberías tener aproximadamente 1/3 de taza.',
   'Erdbeeren rösten: Backofen auf 200°C (400°F) vorheizen. Halbierte Erdbeeren mit 1 Teelöffel Kristallzucker auf einem mit Backpapier ausgelegten Blech vermengen und 20 Minuten rösten, bis sie marmeladig und leicht karamellisiert sind. Vollständig abkühlen lassen, dann zu einem glatten Püree mixen. Du solltest etwa 1/3 Tasse haben.',
   'Assar os morangos: preaqueça o forno a 200°C (400°F). Misture os morangos cortados ao meio com 1 colher de chá do açúcar granulado numa assadeira forrada com papel-manteiga e asse por 20 minutos até ficarem geleados e levemente caramelizados. Esfrie completamente, depois bata até formar um purê liso. Você deve obter cerca de 1/3 de xícara.',
   'Roasting concentrates the strawberry flavor and adds a subtle caramelized note that raw puree can''t give you. You can roast a day ahead and chill overnight.',
   'Rôtir concentre la saveur de la fraise et ajoute une note caramélisée subtile que la purée crue ne peut pas offrir. Vous pouvez rôtir un jour à l''avance et laisser refroidir toute la nuit.',
   'Asar concentra el sabor de la fresa y añade una nota caramelizada sutil que el puré crudo no puede aportar. Puedes asar un día antes y refrigerar toda la noche.',
   'Das Rösten konzentriert den Erdbeergeschmack und bringt eine feine karamellisierte Note, die rohes Püree nicht liefern kann. Du kannst einen Tag im Voraus rösten und über Nacht kühlstellen.',
   'Assar concentra o sabor do morango e acrescenta uma nota caramelizada sutil que o purê cru não oferece. Você pode assar um dia antes e refrigerar durante a noite.'),

  -- 7. Roast cherries
  ('Roast the cherries: preheat oven to 400°F (200°C). Toss pitted halved cherries with 1 teaspoon of the granulated sugar on a parchment-lined tray and roast for 20 minutes until jammy. Cool completely, then blend into a smooth puree. You should have about 1/3 cup.',
   'Rôtir les cerises : préchauffer le four à 200°C. Mélanger les cerises dénoyautées et coupées en deux avec 1 cuillère à café de sucre en poudre sur une plaque recouverte de papier sulfurisé et rôtir 20 minutes jusqu''à ce qu''elles soient confites. Laisser refroidir complètement, puis mixer en purée lisse. Vous devriez obtenir environ 1/3 tasse.',
   'Asar las cerezas: precalentar el horno a 200°C (400°F). Mezclar las cerezas deshuesadas y partidas por la mitad con 1 cucharadita del azúcar granulado en una bandeja con papel pergamino y asar durante 20 minutos hasta que queden mermeladas. Enfriar completamente, luego licuar hasta puré suave. Deberías tener aproximadamente 1/3 de taza.',
   'Kirschen rösten: Backofen auf 200°C (400°F) vorheizen. Entsteinte und halbierte Kirschen mit 1 Teelöffel Kristallzucker auf einem mit Backpapier ausgelegten Blech vermengen und 20 Minuten rösten, bis sie marmeladig sind. Vollständig abkühlen lassen, dann zu glattem Püree mixen. Du solltest etwa 1/3 Tasse haben.',
   'Assar as cerejas: preaqueça o forno a 200°C (400°F). Misture as cerejas sem caroço e cortadas ao meio com 1 colher de chá do açúcar granulado numa assadeira com papel-manteiga e asse por 20 minutos até ficarem geleadas. Esfrie completamente, depois bata até formar um purê liso. Você deve obter cerca de 1/3 de xícara.',
   'Roasting concentrates the cherry flavor and brings out an almost wine-like depth you cannot get from raw fruit.',
   'Rôtir concentre la saveur de la cerise et fait ressortir une profondeur presque vineuse qu''on ne peut pas obtenir avec des fruits crus.',
   'Asar concentra el sabor de la cereza y saca una profundidad casi vinosa que no puedes obtener de la fruta cruda.',
   'Das Rösten konzentriert den Kirschgeschmack und bringt eine fast weinartige Tiefe hervor, die rohe Früchte nicht liefern können.',
   'Assar concentra o sabor da cereja e traz uma profundidade quase vinosa que você não consegue da fruta crua.'),

  -- 8. Roast bananas
  ('Roast the bananas: preheat oven to 400°F (200°C). Place halved bananas (skin-on) on a parchment-lined tray and roast for 15 minutes until the skin is blackened and the flesh is caramelized. Cool slightly, scoop out the flesh, and mash smooth. Set aside — you will whisk the mashed banana with the other base ingredients in the next step.',
   'Rôtir les bananes : préchauffer le four à 200°C. Placer les bananes coupées en deux (avec la peau) sur une plaque recouverte de papier sulfurisé et rôtir 15 minutes jusqu''à ce que la peau soit noircie et la chair caramélisée. Laisser tiédir, prélever la chair et écraser jusqu''à obtenir une purée lisse. Réserver — vous fouetterez la banane écrasée avec les autres ingrédients de la base à l''étape suivante.',
   'Asar los plátanos: precalentar el horno a 200°C (400°F). Colocar los plátanos partidos por la mitad (con cáscara) en una bandeja con papel pergamino y asar durante 15 minutos hasta que la piel esté ennegrecida y la pulpa caramelizada. Enfriar un poco, sacar la pulpa y triturar hasta que quede suave. Reservar — batirás el plátano machacado con los demás ingredientes de la base en el siguiente paso.',
   'Bananen rösten: Backofen auf 200°C (400°F) vorheizen. Halbierte Bananen (mit Schale) auf ein mit Backpapier ausgelegtes Blech legen und 15 Minuten rösten, bis die Schale schwarz und das Fruchtfleisch karamellisiert ist. Etwas abkühlen lassen, das Fruchtfleisch herauslöffeln und glatt zerdrücken. Beiseitestellen — im nächsten Schritt verrührst du die zerdrückte Banane mit den anderen Basiszutaten.',
   'Assar as bananas: preaqueça o forno a 200°C (400°F). Coloque as bananas cortadas ao meio (com casca) numa assadeira com papel-manteiga e asse por 15 minutos até a casca ficar enegrecida e a polpa caramelizada. Esfrie um pouco, retire a polpa e amasse até ficar lisa. Reserve — você vai bater a banana amassada com os outros ingredientes da base no próximo passo.',
   'Roasted bananas taste deeper and more caramel-like than raw — the sugars caramelize in the oven.',
   'Les bananes rôties ont un goût plus profond et plus caramélisé que les bananes crues — les sucres caramélisent au four.',
   'Los plátanos asados tienen un sabor más profundo y caramelizado que los crudos — los azúcares se caramelizan en el horno.',
   'Geröstete Bananen schmecken tiefer und karamelliger als rohe — die Zucker karamellisieren im Ofen.',
   'Bananas assadas têm sabor mais profundo e caramelado do que cruas — os açúcares caramelizam no forno.'),

  -- 9. Roast plums
  ('Roast the plums: preheat oven to 400°F (200°C). Toss halved plums with 1 tablespoon of the granulated sugar on parchment and roast for 20 minutes until jammy. Cool, then blend into a smooth puree (about 1/3 cup).',
   'Rôtir les prunes : préchauffer le four à 200°C. Mélanger les prunes coupées en deux avec 1 cuillère à soupe de sucre en poudre sur du papier sulfurisé et rôtir 20 minutes jusqu''à ce qu''elles soient confites. Laisser refroidir, puis mixer en purée lisse (environ 1/3 tasse).',
   'Asar las ciruelas: precalentar el horno a 200°C (400°F). Mezclar las ciruelas partidas por la mitad con 1 cucharada del azúcar granulado sobre papel pergamino y asar durante 20 minutos hasta que queden mermeladas. Enfriar, luego licuar hasta puré suave (aproximadamente 1/3 de taza).',
   'Pflaumen rösten: Backofen auf 200°C (400°F) vorheizen. Halbierte Pflaumen mit 1 Esslöffel Kristallzucker auf Backpapier vermengen und 20 Minuten rösten, bis sie marmeladig sind. Abkühlen lassen, dann zu glattem Püree mixen (ca. 1/3 Tasse).',
   'Assar as ameixas: preaqueça o forno a 200°C (400°F). Misture as ameixas cortadas ao meio com 1 colher de sopa do açúcar granulado sobre papel-manteiga e asse por 20 minutos até ficarem geleadas. Esfrie, depois bata até formar um purê liso (cerca de 1/3 de xícara).',
   'Roasting concentrates plum flavor and adds a slight caramelized depth raw fruit cannot.',
   'Rôtir concentre la saveur de la prune et ajoute une légère profondeur caramélisée que le fruit cru ne peut pas offrir.',
   'Asar concentra el sabor de la ciruela y añade una ligera profundidad caramelizada que la fruta cruda no puede aportar.',
   'Das Rösten konzentriert den Pflaumengeschmack und bringt eine leicht karamellisierte Tiefe, die rohe Früchte nicht liefern.',
   'Assar concentra o sabor da ameixa e acrescenta uma leve profundidade caramelada que a fruta crua não oferece.'),

  -- 10. Roast apricots
  ('Roast the apricots: preheat oven to 400°F (200°C). Toss halved apricots with 1 tablespoon sugar on parchment, roast 20 minutes until jammy. Cool and blend smooth (you need ~1/3 cup puree).',
   'Rôtir les abricots : préchauffer le four à 200°C. Mélanger les abricots coupés en deux avec 1 cuillère à soupe de sucre sur du papier sulfurisé, rôtir 20 minutes jusqu''à ce qu''ils soient confits. Laisser refroidir et mixer lisse (vous avez besoin d''environ 1/3 tasse de purée).',
   'Asar los albaricoques: precalentar el horno a 200°C (400°F). Mezclar los albaricoques partidos por la mitad con 1 cucharada de azúcar sobre papel pergamino, asar 20 minutos hasta que queden mermelados. Enfriar y licuar suave (necesitas ~1/3 de taza de puré).',
   'Aprikosen rösten: Backofen auf 200°C (400°F) vorheizen. Halbierte Aprikosen mit 1 Esslöffel Zucker auf Backpapier vermengen, 20 Minuten rösten, bis sie marmeladig sind. Abkühlen lassen und glatt mixen (du brauchst ~1/3 Tasse Püree).',
   'Assar os damascos: preaqueça o forno a 200°C (400°F). Misture os damascos cortados ao meio com 1 colher de sopa de açúcar sobre papel-manteiga, asse por 20 minutos até ficarem geleados. Esfrie e bata até ficar liso (você precisa de ~1/3 de xícara de purê).',
   'Roasting concentrates apricot flavor and tempers the tartness.',
   'Rôtir concentre la saveur de l''abricot et tempère l''acidité.',
   'Asar concentra el sabor del albaricoque y atenúa la acidez.',
   'Das Rösten konzentriert den Aprikosengeschmack und mildert die Säure.',
   'Assar concentra o sabor do damasco e suaviza a acidez.'),

  -- 11. Roast grapes
  ('Roast the grapes: preheat oven to 425°F (220°C). Toss halved grapes with 1 tablespoon sugar on parchment, roast 20 minutes until jammy. Cool completely, then blend into puree (about 1/3 cup).',
   'Rôtir les raisins : préchauffer le four à 220°C. Mélanger les raisins coupés en deux avec 1 cuillère à soupe de sucre sur du papier sulfurisé, rôtir 20 minutes jusqu''à ce qu''ils soient confits. Laisser refroidir complètement, puis mixer en purée (environ 1/3 tasse).',
   'Asar las uvas: precalentar el horno a 220°C (425°F). Mezclar las uvas partidas por la mitad con 1 cucharada de azúcar sobre papel pergamino, asar 20 minutos hasta que queden mermeladas. Enfriar completamente, luego licuar hasta puré (aproximadamente 1/3 de taza).',
   'Weintrauben rösten: Backofen auf 220°C (425°F) vorheizen. Halbierte Trauben mit 1 Esslöffel Zucker auf Backpapier vermengen, 20 Minuten rösten, bis sie marmeladig sind. Vollständig abkühlen lassen, dann zu Püree mixen (ca. 1/3 Tasse).',
   'Assar as uvas: preaqueça o forno a 220°C (425°F). Misture as uvas cortadas ao meio com 1 colher de sopa de açúcar sobre papel-manteiga, asse por 20 minutos até ficarem geleadas. Esfrie completamente, depois bata até formar um purê (cerca de 1/3 de xícara).',
   'Roasting grapes concentrates them into a jammy, almost wine-like puree.',
   'Rôtir les raisins les concentre en une purée confite, presque vineuse.',
   'Asar las uvas las concentra en un puré mermelado, casi vinoso.',
   'Das Rösten konzentriert die Weintrauben zu einem marmeladigen, fast weinartigen Püree.',
   'Assar as uvas as concentra em um purê geleado, quase vinoso.');
